// Verify the HMAC that Convex put on this request before doing anything else.
// The secret comes from an environment variable, never from this file.
const crypto = require('crypto');
const secret = $env.WEBHOOK_SECRET;
const input = $input.first().json;
const headers = input.headers || {};
const body = input.body;
const timestamp = String(headers['x-lendloop-timestamp'] || '');
const received = String(headers['x-lendloop-signature'] || '');

const fresh = /^\d{1,12}$/.test(timestamp) && Math.abs(Date.now() / 1000 - Number(timestamp)) <= 300;
let valid = false;
if (secret && fresh && /^[0-9a-f]{64}$/i.test(received)) {
  // Convex signs the exact JSON text it sent. Serialising the parsed body again reproduces it,
  // because both sides use JSON.stringify and key order is preserved.
  const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${JSON.stringify(body)}`).digest();
  valid = crypto.timingSafeEqual(expected, Buffer.from(received, 'hex'));
}
return [{ json: { valid, body, idempotencyKey: String(headers['x-lendloop-idempotency-key'] || '') } }];

// Build the message from the few fields Convex sends.
const { body, idempotencyKey } = $input.first().json;
const tool = body.toolName;
const who = body.counterpartName;
const dates = `${body.startDate} to ${body.endDate}`;
const messages = {
  requested: [`New request to borrow your ${tool}`, `${who} would like to borrow your ${tool} (${dates}). Open LendLoop to approve or decline.`],
  approved: [`Your request for the ${tool} was approved`, `${who} approved your request for the ${tool} (${dates}).`],
  declined: [`Your request for the ${tool} was declined`, `${who} declined your request for the ${tool} (${dates}).`],
  returned: [`Thanks for returning the ${tool}`, `${who} marked the ${tool} as returned. Thank you!`],
};
const [subject, text] = messages[body.event] || [`Update on the ${tool}`, `The loan is now ${body.status}.`];
return [{ json: { idempotencyKey, to: body.recipient.email, subject, text: `Hi ${body.recipient.name}, ${text}` } }];

// Stand in for an email or chat node. Only a masked address and the subject are kept.
// With a real provider, pass idempotencyKey as its idempotency header so a retried delivery is not sent twice.
const m = $input.first().json;
const [user, domain] = String(m.to).split('@');
const masked = `${user.slice(0, 1)}***@${domain || ''}`;
console.log(JSON.stringify({ msg: 'LendLoop notification (mock send)', to: masked, subject: m.subject }));
return [{ json: { ok: true, idempotencyKey: m.idempotencyKey, notification: { to: masked, subject: m.subject } } }];
